 */
function bug_group_action_print_title( $p_action ) {
	require_once( dirname( dirname( __FILE__ ) ) . DIRECTORY_SEPARATOR . 'bug_actiongroup_' . $p_action . '_inc.php' );
	$t_function_name = 'action_' . $p_action . '_print_title';
