      $colname = $aColumns[$i];
      foreach ($conf['user_fields'] as $real_name => $alias)
      {
        if ($aColumns[$i] == $real_name)
        {
          $colname = $alias;
        }
      }

      $row[] = $aRow[$colname];
    }

  }
  $output['aaData'][] = $row;
}

