    {
        return $this->filesystem->listFiles($this->prefix.'/'.$uuid);
    }

    public function getFilesystem()
    {
        return $this->filesystem;
    }

    public function getStreamWrapperPrefix()
    {
        return $this->streamWrapperPrefix;
    }
