		$music=array_merge($music,$ogg);
		$eventSource->send('count',count($music));
		$songs=0;
		foreach($music as $file){
			self::scanFile($file);
			$songs++;
			if($eventSource){
				$eventSource->send('scanned',array('file'=>$file,'count'=>$songs));
