		return 'javascript:deplode(this);return false;';
	}

	public function getCount() {
		return count($this->tiles_array);
	}

	public function getOnClickAction() {
		return 'javascript:openNewGal(\''.$this->stack_name.'\');';
	}

	private $tiles_array;
	private $stack_name;
}

